    if(target.kind==='edge')return passwordAuth?AUTH_EDGE_DEADLINE_MS:EDGE_DEADLINE_MS;
    if(target.base===GATEWAY)return passwordAuth?AUTH_GATEWAY_DEADLINE_MS:GATEWAY_DEADLINE_MS;
