const extraAmount=o=>Number(o?.extra_work_amount||0);
const originalAmount=o=>Number((o?.original_amount!==''&&o?.original_amount!=null)?o.original_amount:o?.amount||0);
const deductionAmount=o=>Number(o?.uncompleted_work_amount||0);
const originalFinanceHome=pages.home;
pages.home=function(){const done=state.orders.filter(o=>o.status==='Выполнена');const extras=done.reduce((a,o)=>a+extraAmount(o),0);const deductions=done.reduce((a,o)=>a+deductionAmount(o),0);return originalFinanceHome()+`<section class="card"><div class="row"><div><h3>Допработы</h3><p class="muted">Отдельно от суммы заявки и выплаты мастеру</p></div><b>${money(extras)}</b></div></section><section class="card"><div class="row"><div><h3>Вычтено за невыполненные работы</h3><p class="muted">Уже уменьшает итоговую сумму выполненных заявок</p></div><b>${money(deductions)}</b></div></section>`};
pages.team=function(){return `<div class="row"><div><h2>Команда</h2><div class="muted">${state.users.length} сотрудников · ${state.masters.length} мастеров</div></div><button class="primary" onclick="openEmployeeForm()">+ Сотрудник</button></div>${state.users.map(u=>{const isMaster=u.role==='master';const done=isMaster?state.orders.filter(o=>o.status==='Выполнена'&&String(o.master_vk_id)===String(u.vk_user_id)):[];const ordersTotal=done.reduce((a,o)=>a+Number(o.amount||0),0);const masterPay=done.reduce((a,o)=>a+payout(o.amount),0);const extras=done.reduce((a,o)=>a+extraAmount(o),0);const deductions=done.reduce((a,o)=>a+deductionAmount(o),0);return `<section class="card"><div class="row"><div><b>${esc(u.full_name)}</b><p class="muted">${esc(u.city||'')} · ${esc(u.phone||'')}</p></div><span class="status info">${esc(ROLE_NAMES[u.role]||u.role)}</span></div>${isMaster?`<div class="grid"><div class="metric"><span class="muted">Выполнено заявок</span><strong>${done.length}</strong></div><div class="metric"><span class="muted">Сумма выполненных заявок</span><strong>${money(ordersTotal)}</strong></div><div class="metric"><span class="muted">Выплата мастеру</span><strong>${money(masterPay)}</strong></div><div class="metric"><span class="muted">Допработы</span><strong>${money(extras)}</strong></div><div class="metric"><span class="muted">Вычтено невыполненных работ</span><strong>${money(deductions)}</strong></div></div>`:''}</section>`}).join('')||'<p class="muted">Сотрудников пока нет.</p>'}`};
function completionFieldsHtml(o){const extraYes=extraTruthy(o?.extra_work_done),unfinishedYes=extraTruthy(o?.uncompleted_work_done);return `<div id="completionBlock"><div class="card"><label>Все заявленные работы выполнены?</label><select name="uncompleted_work_done" id="unfinishedDone"><option value="false" ${!unfinishedYes?'selected':''}>Да, всё выполнено</option><option value="true" ${unfinishedYes?'selected':''}>Нет, часть не выполнена</option></select><div id="unfinishedDetails" style="display:${unfinishedYes?'block':'none'}"><textarea name="uncompleted_work_description" placeholder="Какие работы не выполнены">${esc(o?.uncompleted_work_description||'')}</textarea><input type="number" name="uncompleted_work_amount" min="0" step="0.01" placeholder="Стоимость невыполненных работ" value="${unfinishedYes?esc(o?.uncompleted_work_amount||''):''}"><p class="muted">Эта сумма будет вычтена из исходной стоимости заявки до расчёта выплат.</p></div></div><div class="card"><label>Были допработы?</label><select name="extra_work_done" id="extraWorkDone"><option value="false" ${!extraYes?'selected':''}>Нет</option><option value="true" ${extraYes?'selected':''}>Да</option></select><div id="extraWorkDetails" style="display:${extraYes?'block':'none'}"><textarea name="extra_work_description" placeholder="Какие допработы">${esc(o?.extra_work_description||'')}</textarea><input type="number" name="extra_work_amount" min="0" step="0.01" placeholder="Сколько взяли с клиента" value="${extraYes?esc(o?.extra_work_amount||''):''}"><p class="muted">Допработы учитываются отдельно и не входят в основную сумму заявки.</p></div></div></div>`}
function bindCompletionToggles(form){const status=form.elements.status,extra=form.elements.extra_work_done,extraDetails=form.querySelector('#extraWorkDetails'),unfinished=form.elements.uncompleted_work_done,unfinishedDetails=form.querySelector('#unfinishedDetails'),block=form.querySelector('#completionBlock');const sync=()=>{const completed=status.value==='Выполнена';block.style.display=completed?'block':'none';extraDetails.style.display=completed&&extra.value==='true'?'block':'none';unfinishedDetails.style.display=completed&&unfinished.value==='true'?'block':'none';recalcFinal(form)};status.onchange=sync;extra.onchange=sync;unfinished.onchange=sync;sync()}
function recalcFinal(form){const base=Number(form.elements.original_amount?.value||0);const deduction=form.elements.status?.value==='Выполнена'&&form.elements.uncompleted_work_done?.value==='true'?Number(form.elements.uncompleted_work_amount?.value||0):0;const final=Math.max(0,base-deduction);const f=form.querySelector('#finalAmount');const p=form.querySelector('#calcPay');if(f)f.textContent=money(final);if(p)p.textContent=money(form.elements.master_vk_id?.value?payout(final):0)}
openOrder=function(id){const o=state.orders.find(x=>String(x.id)===String(id));if(!o)return;const extraYes=extraTruthy(o.extra_work_done),unfinishedYes=extraTruthy(o.uncompleted_work_done);openModal(`<h2>${esc(o.id)}</h2><p><b>${esc(o.work)}</b></p><p>${esc(o.client)} · ${esc(o.phone||'')}</p><p>${esc(o.address)}</p><label>Статус</label><select id="quickStatus">${STATUSES.map(s=>`<option ${o.status===s?'selected':''}>${s}</option>`).join('')}</select><label>Мастер</label><select id="quickMaster"><option value="">Не назначен</option>${state.masters.map(m=>`<option value="${esc(m.vk_user_id)}" ${String(o.master_vk_id||'')===String(m.vk_user_id)?'selected':''}>${esc(m.full_name)}</option>`).join('')}</select><p>Исходная сумма: <b>${money(originalAmount(o))}</b></p>${unfinishedYes?`<p>Вычтено: <b>${money(o.uncompleted_work_amount)}</b> · ${esc(o.uncompleted_work_description||'')}</p>`:''}<p>Итоговая сумма заявки: <b>${money(o.amount)}</b></p><p>Выплата мастеру: <b>${money(o.master_vk_id?payout(o.amount):0)}</b></p><div id="quickCompletion" style="display:${o.status==='Выполнена'?'block':'none'}"><label>Все заявленные работы выполнены?</label><select id="quickUnfinishedDone"><option value="false" ${!unfinishedYes?'selected':''}>Да</option><option value="true" ${unfinishedYes?'selected':''}>Нет</option></select><div id="quickUnfinishedDetails" style="display:${unfinishedYes?'block':'none'}"><textarea id="quickUnfinishedDescription" placeholder="Какие работы не выполнены">${esc(o.uncompleted_work_description||'')}</textarea><input id="quickUnfinishedAmount" type="number" min="0" step="0.01" placeholder="Стоимость невыполненных работ" value="${unfinishedYes?esc(o.uncompleted_work_amount||''):''}"></div><label>Были допработы?</label><select id="quickExtraDone"><option value="false" ${!extraYes?'selected':''}>Нет</option><option value="true" ${extraYes?'selected':''}>Да</option></select><div id="quickExtraDetails" style="display:${extraYes?'block':'none'}"><textarea id="quickExtraDescription" placeholder="Какие допработы">${esc(o.extra_work_description||'')}</textarea><input id="quickExtraAmount" type="number" min="0" step="0.01" placeholder="Сколько взяли с клиента" value="${extraYes?esc(o.extra_work_amount||''):''}"></div></div>${extraYes?`<p class="muted">Допработы: ${esc(o.extra_work_description)} · <b>${money(o.extra_work_amount)}</b></p>`:''}<div class="two"><button class="primary" onclick="saveQuickOrder('${esc(o.id)}')">Сохранить статус</button><button class="secondary" onclick="openOrderForm('${esc(o.id)}')">Редактировать</button></div><p id="quickMsg" class="muted"></p>`);const st=$('#quickStatus'),extra=$('#quickExtraDone'),extraDetails=$('#quickExtraDetails'),unfinished=$('#quickUnfinishedDone'),unfinishedDetails=$('#quickUnfinishedDetails'),block=$('#quickCompletion');const sync=()=>{const completed=st.value==='Выполнена';block.style.display=completed?'block':'none';extraDetails.style.display=completed&&extra.value==='true'?'block':'none';unfinishedDetails.style.display=completed&&unfinished.value==='true'?'block':'none'};st.onchange=sync;extra.onchange=sync;unfinished.onchange=sync;sync()};
saveQuickOrder=async function(id){const o=state.orders.find(x=>String(x.id)===String(id)),msg=$('#quickMsg');if(!o||state.busy)return;state.busy=true;msg.textContent='Сохраняем…';try{const status=$('#quickStatus').value;const extraDone=status==='Выполнена'&&$('#quickExtraDone')?.value==='true';const unfinishedDone=status==='Выполнена'&&$('#quickUnfinishedDone')?.value==='true';const payload={id,status,master_vk_id:$('#quickMaster').value,original_amount:originalAmount(o),extra_work_done:extraDone,extra_work_description:extraDone?($('#quickExtraDescription')?.value||''):'',extra_work_amount:extraDone?Number($('#quickExtraAmount')?.value||0):0,uncompleted_work_done:unfinishedDone,uncompleted_work_description:unfinishedDone?($('#quickUnfinishedDescription')?.value||''):'',uncompleted_work_amount:unfinishedDone?Number($('#quickUnfinishedAmount')?.value||0):0};const d=await api('updateOrder',payload);if(!d.ok)throw new Error(d.error);const i=state.orders.findIndex(x=>String(x.id)===String(id));state.orders[i]=d.order;closeModal();show(state.page)}catch(e){msg.textContent=e.message}finally{state.busy=false}};
openOrderForm=function(id){const o=id?state.orders.find(x=>String(x.id)===String(id)):null;const base=originalAmount(o||{});openModal(`<h2>${o?'Редактировать':'Новая заявка'}</h2><form id="orderForm" class="form"><input name="client" placeholder="Клиент" required value="${esc(o?.client||'')}"><input name="phone" placeholder="Телефон" value="${esc(o?.phone||'')}"><input name="address" placeholder="Адрес" required value="${esc(o?.address||'')}"><input name="work" placeholder="Работа" required value="${esc(o?.work||'')}"><div class="two"><input type="date" name="scheduled_date" value="${esc(o?.scheduled_date||'')}"><input type="time" name="scheduled_time" value="${esc(o?.scheduled_time||'')}"></div><select name="status">${STATUSES.map(s=>`<option ${o?.status===s?'selected':''}>${s}</option>`).join('')}</select><select name="master_vk_id"><option value="">Не назначен</option>${state.masters.map(m=>`<option value="${esc(m.vk_user_id)}" ${String(o?.master_vk_id||'')===String(m.vk_user_id)?'selected':''}>${esc(m.full_name)}</option>`).join('')}</select><label>Исходная сумма заявки</label><input type="number" name="original_amount" min="0" step="0.01" placeholder="Исходная сумма" value="${esc(o?base:'')}"><div class="card"><span class="muted">Итоговая сумма после вычетов</span><b id="finalAmount">${money(o?.amount||base)}</b><span class="muted">Расчёт мастеру</span><b id="calcPay">${money(o?.master_vk_id?payout(o?.amount):0)}</b><small class="muted">выплаты считаются от итоговой суммы</small></div>${completionFieldsHtml(o)}<select name="source">${(state.sources.length?state.sources:[{source:'VK'}]).map(s=>`<option ${o?.source===s.source?'selected':''}>${esc(s.source)}</option>`).join('')}</select><textarea name="comment" placeholder="Комментарий">${esc(o?.comment||'')}</textarea><button class="primary wide" type="submit">Сохранить</button><p id="formMsg" class="muted"></p></form>`);const form=$('#orderForm'),baseInput=form.elements.original_amount,master=form.elements.master_vk_id,deduct=form.elements.uncompleted_work_amount;const recalc=()=>recalcFinal(form);baseInput.oninput=recalc;master.onchange=recalc;if(deduct)deduct.oninput=recalc;bindCompletionToggles(form);form.onsubmit=async e=>{e.preventDefault();if(state.busy)return;const f=Object.fromEntries(new FormData(form));f.original_amount=Number(f.original_amount||0);f.extra_work_done=f.status==='Выполнена'&&f.extra_work_done==='true';f.extra_work_amount=f.extra_work_done?Number(f.extra_work_amount||0):0;if(!f.extra_work_done)f.extra_work_description='';f.uncompleted_work_done=f.status==='Выполнена'&&f.uncompleted_work_done==='true';f.uncompleted_work_amount=f.uncompleted_work_done?Number(f.uncompleted_work_amount||0):0;if(!f.uncompleted_work_done)f.uncompleted_work_description='';if(o)f.id=o.id;const msg=$('#formMsg');msg.textContent='Сохраняем…';setBusy(form,true);try{const d=await api(o?'updateOrder':'createOrder',f);if(!d.ok)throw new Error(d.error);if(o){const i=state.orders.findIndex(x=>String(x.id)===String(o.id));state.orders[i]=d.order}else state.orders.unshift(d.order);state.busy=false;closeModal();show('orders')}catch(err){msg.textContent=err.message;setBusy(form,false)}finally{state.busy=false}}};

