function selectedWeekHours(days){const first=days.find(d=>extraTruthy(d.is_working))||days[0];return{start:hourValue(first?.work_start,'09'),end:hourValue(first?.work_end,'18')}}
function weeklyCalendarHtml(masterId,editable=true){const week=masterWeekStart||mondayOf();const days=weekDays(masterId,week);const hours=selectedWeekHours(days);return `<section class="card"><div class="row"><button class="secondary" onclick="changeMasterWeek(-7)">←</button><div style="text-align:center"><b>Неделя ${humanDay(week)}–${humanDay(addDaysIso(week,6))}</b><div class="muted">Выберите дни и общий интервал</div></div><button class="secondary" onclick="changeMasterWeek(7)">→</button></div></section>${editable?`<section class="card"><h3>Рабочие дни</h3><div class="row" style="flex-wrap:wrap;gap:8px"><button class="secondary" onclick="setMasterDays('all')">Все дни</button><button class="secondary" onclick="setMasterDays('weekdays')">Будни</button><button class="secondary" onclick="setMasterDays('none')">Снять все</button></div><div class="row" style="flex-wrap:wrap;gap:8px;margin-top:12px">${days.map((d,i)=>`<label class="secondary" style="display:flex;gap:6px;align-items:center"><input class="masterDayOn" data-i="${i}" type="checkbox" ${extraTruthy(d.is_working)?'checked':''}> ${ruWeek[i]}</label>`).join('')}</div><div class="two" style="margin-top:14px"><label>С ${hourSelect('masterCommonStart',hours.start+':00')}</label><label>До ${hourSelect('masterCommonEnd',hours.end+':00')}</label></div><p class="muted">Время применяется ко всем отмеченным дням. Минуты не используются.</p></section>`:''}${days.map((d,i)=>{const orders=masterOrdersOn(d.date);const on=extraTruthy(d.is_working);return `<section class="card"><div class="row"><div><b>${ruWeek[i]} · ${humanDay(d.date)}</b><div class="muted masterDayLabel" data-i="${i}">${on?String(hours.start).padStart(2,'0')+':00–'+String(hours.end).padStart(2,'0')+':00':'Выходной'}</div></div>${orders.length?`<span class="status info">${orders.length} заяв.</span>`:''}</div>${orders.length?`<div style="margin-top:12px">${orders.map(o=>`<button class="secondary wide" style="margin-top:8px;text-align:left" onclick="openOrder('${esc(o.id)}')"><b>${esc(o.time_slot||o.scheduled_time||'Без времени')}</b> · ${esc(o.work)}<br><span class="muted">${esc(o.address)} · ${esc(o.status)}</span></button>`).join('')}</div>`:'<p class="muted" style="margin-top:10px">Заявок нет</p>'}</section>`}).join('')}${editable?`<button class="primary wide" onclick="saveMasterWeek()">Сохранить график недели</button><p id="weekSaveMsg" class="muted"></p>`:''}`}
function bindWeekToggles(){document.querySelectorAll('.masterDayOn').forEach(ch=>ch.onchange=refreshMasterDayLabels);const s=$('#masterCommonStart'),e=$('#masterCommonEnd');if(s)s.onchange=refreshMasterDayLabels;if(e)e.onchange=refreshMasterDayLabels;refreshMasterDayLabels()}
function refreshMasterDayLabels(){const s=String($('#masterCommonStart')?.value||9).padStart(2,'0')+':00',e=String($('#masterCommonEnd')?.value||18).padStart(2,'0')+':00';document.querySelectorAll('.masterDayLabel').forEach(el=>{const i=el.dataset.i,on=document.querySelector(`.masterDayOn[data-i="${i}"]`)?.checked;el.textContent=on?`${s}–${e}`:'Выходной'})}
function setMasterDays(mode){document.querySelectorAll('.masterDayOn').forEach((ch,i)=>{ch.checked=mode==='all'||(mode==='weekdays'&&i<5)});refreshMasterDayLabels()}
function changeMasterWeek(delta){masterWeekStart=addDaysIso(masterWeekStart||mondayOf(),delta);show('dispatch');setTimeout(bindWeekToggles,0)}
async function loadSavedMasterWeek(masterId,week){try{const d=await api('bootstrap');if(!d?.ok)return false;masterSchedule=normalizedScheduleRows(d.masterSchedule||[]);return scheduleFor(masterId,week).length===7}catch(_){return false}}
