(()=>{const prevHome=pages.home;function fmtSlot(o){if(o.time_slot)return o.time_slot;const t=String(o.scheduled_time||'').slice(0,5);if(!t)return 'Без времени';const h=Number(t.slice(0,2));return `${t}–${String((h+1)%24).padStart(2,'0')}:00`}function flagChips(o){const a=[];if(o.wall_material)a.push(`🧱 ${esc(o.wall_material)}`);if(o.wall_over_3m)a.push('🪜 > 3 м');if(o.possible_extra_work)a.push('🛠 Доп. работы');if(o.comment)a.push('💬 Комментарий');return a.length?`<div class="dashChips">${a.map(x=>`<span>${x}</span>`).join('')}</div>`:''}function upcoming(){const today=new Date().toISOString().slice(0,10);return (state.orders||[]).filter(o=>String(o.status)!=='Отменена'&&String(o.scheduled_date||'')>=today).sort((a,b)=>String(a.scheduled_date+a.scheduled_time).localeCompare(String(b.scheduled_date+b.scheduled_time))).slice(0,3)}function upcomingHtml(){const a=upcoming();return `<section class="dashSection"><div class="row"><h2>Ближайшие заявки</h2><button class="linkBtn" onclick="show('orders')">Все заявки →</button></div>${a.length?a.map(o=>`<button class="dashOrder" onclick="openOrder('${esc(o.id)}')"><div class="dashOrderTime"><b>${esc(String(o.scheduled_date||'').slice(5)||'')}</b><span>${esc(fmtSlot(o))}</span></div><div class="dashOrderBody"><strong>${esc(o.work||'Заявка')}</strong><span>${esc(o.address||'')}</span><small>${esc(o.master_name||'Не назначен')}</small>${flagChips(o)}</div><div class="dashArrow">›</div></button>`).join(''):'<section class="card"><p class="muted">Ближайших заявок нет.</p></section>'}</section>`}function metricsHtml(dispatcher){const done=state.orders.filter(o=>o.status==='Выполнена'),active=state.orders.filter(o=>o.status==='В работе'),rev=done.reduce((s,o)=>s+Number(o.amount||0),0);const today=new Date().toISOString().slice(0,10),todayCount=state.orders.filter(o=>String(o.scheduled_date||'')===today&&o.status!=='Отменена').length;const cards=dispatcher?[['📋','В работе',active.length,'Активных заявок'],['🗓️','Сегодня',todayCount,'Заявок на сегодня'],['✅','Выполнено',done.length,'Всего выполнено'],['👥','Мастеров',state.masters.length,'В команде']]:[['📋','Заявок',state.orders.length,'Всего заявок'],['👥','Мастеров',state.masters.length,'В команде'],['🕒','В работе',active.length,'Активных заявок'],['₽','Выручка',money(rev),'По выполненным']];return `<div class="dashMetrics">${cards.map(c=>`<section class="card dashMetric"><span class="dashIcon">${c[0]}</span><span class="muted">${c[1]}</span><strong>${c[2]}</strong><small>${c[3]}</small></section>`).join('')}</div>`}pages.home=function(){if(typeof isMasterPreview==='function'&&isMasterPreview())return prevHome();const dispatcher=typeof isDispatcherPreview==='function'&&isDispatcherPreview();let html=`${typeof loadChart==='function'?loadChart():''}${metricsHtml(dispatcher)}${upcomingHtml()}`;if(dispatcher)html+=`<section class="card"><div class="row"><div><h3>Отчёт по мастерам</h3><p class="muted">Неделя / месяц · выполненные заявки и зарплата</p></div><button class="primary" onclick="dispatcherReportAnchor=new Date();dispatcherReportKind='week';showDispatcherReport()">Создать</button></div></section>`;return html};})();

