// Source: master-profile-v4.js
(()=>{
function masterAvatar(u){const src=u?.avatar_url||'';return src?`<img src="${esc(src)}" alt="Фото мастера" style="width:88px;height:88px;border-radius:24px;object-fit:cover;border:1px solid #315271">`:`<div style="width:88px;height:88px;border-radius:24px;display:grid;place-items:center;background:#17304a;border:1px solid #315271;font-size:30px;font-weight:900">${esc((u?.full_name||'М').trim().charAt(0).toUpperCase())}</div>`}
function compactWeek(masterId){const week=masterWeekStart||mondayOf();const days=weekDays(masterId,week);const hours=selectedWeekHours(days);return `<section class="card"><div class="row"><button class="secondary" onclick="changeMasterWeek(-7)">←</button><div style="text-align:center"><b>${humanDay(week)}–${humanDay(addDaysIso(week,6))}</b><div class="muted">Рабочая неделя</div></div><button class="secondary" onclick="changeMasterWeek(7)">→</button></div><div style="margin-top:14px"><div class="muted" style="margin-bottom:8px">Дни работы</div><div style="display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px">${days.map((d,i)=>`<label style="display:grid;place-items:center;gap:4px;padding:10px 4px;border:1px solid #2e4965;border-radius:12px;background:#102238;font-size:12px"><input class="masterDayOn" data-i="${i}" type="checkbox" ${extraTruthy(d.is_working)?'checked':''}><span>${ruWeek[i]}</span></label>`).join('')}</div></div><div class="two" style="margin-top:14px"><label>Начало${hourSelect('masterCommonStart',hours.start+':00')}</label><label>Конец${hourSelect('masterCommonEnd',hours.end+':00')}</label></div><div class="row" style="margin-top:10px;gap:8px;flex-wrap:wrap"><button class="secondary" onclick="setMasterDays('weekdays')">Будни</button><button class="secondary" onclick="setMasterDays('all')">Все дни</button><button class="ghost" onclick="setMasterDays('none')">Снять</button></div></section>${days.map((d,i)=>{const orders=masterOrdersOn(d.date);if(!orders.length)return '';return `<section class="card"><div class="row"><b>${ruWeek[i]} · ${humanDay(d.date)}</b><span class="status info">${orders.length} заяв.</span></div>${orders.map(o=>`<button class="secondary wide" style="margin-top:8px;text-align:left" onclick="openOrder('${esc(o.id)}')"><b>${esc(o.time_slot||o.scheduled_time||'Без времени')}</b> · ${esc(o.work)}<br><span class="muted">${esc(o.address)}</span></button>`).join('')}</section>`}).join('')}<button class="primary wide" onclick="saveMasterWeek()">Сохранить график</button><p id="weekSaveMsg" class="muted"></p>`}
const oldHome=pages.home;pages.home=function(){if(!liveMasterMode())return oldHome();const u=liveMasterUser(),orders=ownOrders(),done=completedOwnOrders(),active=orders.filter(o=>o.status==='В работе');return `<section class="hero"><div class="eyebrow">КАБИНЕТ МАСТЕРА</div><div class="row" style="align-items:center"><div><h2>${esc(u?.full_name||'Мастер')}</h2><p class="muted">${esc(u?.city||'')}</p></div>${masterAvatar(u)}</div></section><div class="grid masterHomeGrid"><div class="card metric"><span class="muted">В работе</span><strong>${active.length}</strong></div><div class="card metric"><span class="muted">Выполнено</span><strong>${done.length}</strong></div><div class="card metric"><span class="muted">Моя выплата</span><strong>${money(ownPayoutTotal())}</strong></div><div class="card metric"><span class="muted">Допработы</span><strong>${money(ownExtraTotal())}</strong></div></div><section class="card"><h3>Ближайшие заявки</h3>${active.slice(0,4).map(o=>`<button class="secondary wide" style="margin:8px 0;text-align:left" onclick="openOrder('${esc(o.id)}')"><b>${esc(o.scheduled_date||'')} ${esc(o.time_slot||o.scheduled_time||'')}</b><br>${esc(o.work)}<br><span class="muted">${esc(o.address||'')}</span></button>`).join('')||'<p class="muted">Активных заявок нет.</p>'}</section>`};
const oldDispatch=pages.dispatch;pages.dispatch=function(){if(!liveMasterMode())return oldDispatch();masterWeekStart=masterWeekStart||mondayOf();setTimeout(bindWeekToggles,0);return `<div class="row"><div><h2>Мой график</h2><div class="muted">Отметьте дни и выберите единое время работы</div></div><button class="secondary" onclick="masterWeekStart=mondayOf();show('dispatch');setTimeout(bindWeekToggles,0)">Сегодня</button></div>${compactWeek(liveMasterId())}`};
const oldTeam=pages.team;pages.team=function(){if(!liveMasterMode())return oldTeam();const u=liveMasterUser(),m=typeof employeeMasterData==='function'?employeeMasterData(u):null,orders=ownOrders(),done=completedOwnOrders();return `<h2>Профиль мастера</h2><section class="card"><div class="row" style="align-items:center"><div>${masterAvatar(u)}</div><div style="flex:1"><h3 style="margin:0 0 6px">${esc(u?.full_name||'Мастер')}</h3><div class="muted">${esc(u?.city||'—')}</div><div class="muted">${esc(u?.phone||'—')}</div></div></div><label style="display:block;margin-top:14px">Фото профиля</label><input id="masterAvatarInput" type="file" accept="image/*" capture="user"><p class="muted" style="font-size:12px">Фото можно выбрать сейчас; постоянное сохранение в профиль подключаем следующим обновлением.</p></section><div class="grid masterHomeGrid"><div class="card metric"><span class="muted">В работе</span><strong>${orders.filter(o=>o.status==='В работе').length}</strong></div><div class="card metric"><span class="muted">Выполнено</span><strong>${done.length}</strong></div><div class="card metric"><span class="muted">Моя выплата</span><strong>${money(ownPayoutTotal())}</strong></div><div class="card metric"><span class="muted">Допработы</span><strong>${money(ownExtraTotal())}</strong></div></div><section class="card"><h3>Расчёт зарплаты</h3><p class="muted">По выполненным заявкам</p><div class="row"><span>Начислено мастеру</span><b>${money(ownPayoutTotal())}</b></div>${ownExtraTotal()?`<div class="row" style="margin-top:8px"><span>Допработы</span><b>${money(ownExtraTotal())}</b></div>`:''}</section><section class="card"><h3>График</h3><button class="primary wide" onclick="show('dispatch');setTimeout(bindWeekToggles,0)">Настроить рабочие дни и время</button></section>${typeof isMasterPreview==='function'&&isMasterPreview()?'<button class="secondary wide" onclick="exitMasterPreview()">← Вернуться в профиль владельца</button>':''}`;setTimeout(()=>{const inp=document.getElementById('masterAvatarInput');if(inp)inp.onchange=()=>{const f=inp.files&&inp.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{const img=inp.closest('.card').querySelector('img,div[style*="width:88px"]');if(img&&img.tagName==='IMG')img.src=r.result;else{const holder=inp.closest('.card').querySelector('div[style*="width:88px"]');if(holder){const im=document.createElement('img');im.src=r.result;im.style='width:88px;height:88px;border-radius:24px;object-fit:cover;border:1px solid #315271';holder.replaceWith(im)}}};r.readAsDataURL(f)}},0);return ''};
})();

