function attentionData(){const today=dToday(),orders=dOrders();return {unassigned:orders.filter(o=>dActive(o)&&!o.master_name&&!o.master_vk_id&&!o.master_id),today:orders.filter(o=>dActive(o)&&String(o.scheduled_date||'').slice(0,10)===today),overdue:orders.filter(o=>dActive(o)&&o.scheduled_date&&String(o.scheduled_date).slice(0,10)<today),report:orders.filter(o=>dDone(o)&&String(o.report_review_status||'').toLowerCase()==='pending')}}
