    if(window.innerWidth>=1050&&window.BOS_DISPATCHER_ATTENTION_V123?.setFilter&&['overdue','unassigned','conflict','reschedule','all'].includes(value))window.BOS_DISPATCHER_ATTENTION_V123.setFilter(value);
