function ids(x){return [x?.id,x?.staff_id,x?.master_staff_id,x?.vk_user_id,x?.user_id,x?.external_id].filter(Boolean).map(String)}
function same(a,b){const s=new Set(ids(a));return ids(b).some(x=>s.has(x))}
