// Source: master-schedule-presets-v17.js
(()=>{
'use strict';
function masterScheduleMode(){return typeof liveMasterMode==='function'&&liveMasterMode()}
function pad2(n){return String(n).padStart(2,'0')}
function isoDateLocal(y,m,d){return `${y}-${pad2(m+1)}-${pad2(d)}`}
function allDatesInCurrentCalendar(){return window.BOS_MASTER_CALENDAR.dates()}
function applySchedulePreset(kind){if(!masterScheduleMode())return;const dates=allDatesInCurrentCalendar();dates.forEach(date=>{const d=new Date(date+'T12:00:00'),day=d.getDay(),dr=window.BOS_MASTER_CALENDAR.draftFor(date);if(kind==='weekdays')dr.is_working=day>=1&&day<=5;else if(kind==='all')dr.is_working=true;else if(kind==='off')dr.is_working=false;});renderMonthCalendar()}
function applyScheduleDays(){if(!masterScheduleMode())return;const checked=[...document.querySelectorAll('[data-bos-weekday]:checked')].map(x=>Number(x.dataset.bosWeekday));const set=new Set(checked);allDatesInCurrentCalendar().forEach(date=>{const d=new Date(date+'T12:00:00'),dr=window.BOS_MASTER_CALENDAR.draftFor(date);dr.is_working=set.has(d.getDay())});renderMonthCalendar()}
window.applyMasterSchedulePreset=applySchedulePreset;
window.applyMasterScheduleDays=applyScheduleDays;
const oldRender=window.renderMonthCalendar;
window.renderMonthCalendar=function(){oldRender();const host=document.getElementById('masterMonthCalendar');if(!host||!masterScheduleMode()||host.querySelector('.bosSchedulePresets'))return;const card=host.querySelector('.card');if(!card)return;const box=document.createElement('section');box.className='card bosSchedulePresets';box.innerHTML=`<div class="row"><div><h3 style="margin:0">Быстрый выбор графика</h3><div class="muted">Можно выбрать готовый вариант или нужные дни недели</div></div></div><div class="bosPresetBtns"><button type="button" class="secondary" onclick="applyMasterSchedulePreset('weekdays')">Будние дни</button><button type="button" class="secondary" onclick="applyMasterSchedulePreset('all')">Все дни</button><button type="button" class="secondary" onclick="applyMasterSchedulePreset('off')">Все выходные</button></div><div class="bosWeekdayPick"><label><input type="checkbox" data-bos-weekday="1"> Пн</label><label><input type="checkbox" data-bos-weekday="2"> Вт</label><label><input type="checkbox" data-bos-weekday="3"> Ср</label><label><input type="checkbox" data-bos-weekday="4"> Чт</label><label><input type="checkbox" data-bos-weekday="5"> Пт</label><label><input type="checkbox" data-bos-weekday="6"> Сб</label><label><input type="checkbox" data-bos-weekday="0"> Вс</label></div><button type="button" class="primary wide" onclick="applyMasterScheduleDays()">Применить выбранные дни</button>`;host.insertBefore(box,card);};
const oldSelect=window.selectMasterCalendarDay;window.selectMasterCalendarDay=function(date){oldSelect(date);window.renderMonthCalendar()};
const oldChange=window.changeMasterCalendarMonth;window.changeMasterCalendarMonth=function(delta){oldChange(delta);window.renderMonthCalendar()};
const oldSave=window.saveMasterCalendarMonth;window.saveMasterCalendarMonth=async function(){return oldSave()};
const oldDispatch=pages.dispatch;pages.dispatch=function(){const html=oldDispatch();if(masterScheduleMode())setTimeout(()=>window.renderMonthCalendar(),0);return html};
const st=document.createElement('style');st.textContent='.bosSchedulePresets{margin-bottom:12px}.bosPresetBtns{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:12px 0}.bosWeekdayPick{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px;margin:8px 0 12px}.bosWeekdayPick label{display:flex;flex-direction:column;align-items:center;gap:6px;font-size:12px;padding:8px 4px;border:1px solid #293f58;border-radius:10px}.bosWeekdayPick input{width:20px;height:20px}@media(max-width:560px){.bosPresetBtns{grid-template-columns:1fr 1fr}.bosPresetBtns button:last-child{grid-column:1/-1}.bosWeekdayPick{grid-template-columns:repeat(4,minmax(0,1fr))}}';document.head.appendChild(st);
})();

