// Source: master-memo-v20.js
(()=>{
'use strict';
function memoMasterMode(){return (typeof liveMasterMode==='function'&&liveMasterMode())||(typeof isMasterPreview==='function'&&isMasterPreview())||String(state.user?.role||'')==='master'}
function memoCard(title,desc,kind){return `<button class="card masterMemoCard" type="button" onclick="openMasterMemoItem('${kind}')"><div><h3>${title}</h3><p class="muted">${desc}</p></div><span>Открыть ›</span></button>`}
function masterMemoHtml(){return `<section class="hero"><div class="eyebrow">МАСТЕРУ</div><h2>Памятка</h2><p class="muted">Документы, прайс и рабочие подсказки всегда под рукой.</p></section><div class="masterMemoGrid">${memoCard('Акты выполненных работ','Бланки актов, которые нужно заполнять по заявкам.','acts')}${memoCard('Листы замера','Бланки для замеров и фиксации размеров.','measurements')}${memoCard('Прайс услуг','Актуальные услуги и стоимость работ.','price')}${memoCard('Подсказки по работе','Правила работы с заявкой, клиентом и отчётами.','tips')}</div>`}
window.openMasterMemoItem=function(kind){const data={acts:['Акты выполненных работ','Здесь будут храниться актуальные бланки актов выполненных работ.'],measurements:['Листы замера','Здесь будут храниться листы замера и другие бланки для замерных заявок.'],price:['Прайс услуг','Здесь будет актуальный прайс услуг для мастеров.'],tips:['Подсказки по работе','Здесь будут инструкции, памятки и рабочие подсказки для мастеров.']}[kind]||['Памятка','Материал пока не добавлен.'];openModal(`<h2>${data[0]}</h2><section class="card"><p>${data[1]}</p><p class="muted">Материалы сможет добавлять владелец. Файлы и инструкции появятся здесь после загрузки.</p></section><button class="secondary wide" onclick="closeModal()">Закрыть</button>`)};
const oldShow=window.show;
window.show=function(name){if(name==='memo'&&memoMasterMode()){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page==='memo'));$('#content').innerHTML=masterMemoHtml();window.fixMasterMemoNav?.();return}oldShow(name);window.fixMasterMemoNav?.()};
function fix(){const nav=document.querySelector('nav');if(!nav||!memoMasterMode())return;let memo=nav.querySelector('button[data-page="memo"]');if(!memo){memo=document.createElement('button');memo.dataset.page='memo';memo.textContent='Памятка';memo.onclick=()=>show('memo');nav.appendChild(memo)}const buttons=[...nav.querySelectorAll('button')];const base=buttons.filter(b=>b!==memo).slice(0,4);base.forEach(b=>b.style.display='');buttons.filter(b=>!base.includes(b)&&b!==memo).forEach(b=>b.style.display='none');memo.style.display='';nav.style.gridTemplateColumns='repeat(5,minmax(0,1fr))'}
window.fixMasterMemoNav=fix;setTimeout(fix,0);
const style=document.createElement('style');style.textContent=`.masterMemoGrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.masterMemoCard{width:100%;text-align:left;display:flex;justify-content:space-between;align-items:center;gap:14px;cursor:pointer}.masterMemoCard h3{margin:0 0 5px}.masterMemoCard p{margin:0}.masterMemoCard>span{white-space:nowrap}.masterMemoGrid button{color:inherit}@media(max-width:620px){.masterMemoGrid{grid-template-columns:1fr}nav:has(button[data-page="memo"]){font-size:11px}nav:has(button[data-page="memo"]) button{padding-left:3px;padding-right:3px}}`;document.head.appendChild(style);
})();

