// Source: api-integrations-v26.js
(()=>{'use strict';
const URL='https://obsropbslfwtanyspjbi.supabase.co/functions/v1/integration-api';
const FIELDS=[['external_id','ID заявки во внешней системе'],['client','Клиент'],['phone','Телефон'],['address','Адрес'],['work','Работа / услуга'],['status','Статус'],['amount','Сумма'],['original_amount','Исходная сумма'],['scheduled_date','Дата выполнения'],['scheduled_time','Время выполнения'],['time_slot','Временной слот'],['source','Источник'],['city','Город'],['comment','Комментарий'],['source_updated_at','Дата изменения во внешней системе']];
async function call(action,p={}){const h=window.BOS_AUTH_HEADERS?await window.BOS_AUTH_HEADERS():{};h['Content-Type']='application/json';const r=await fetch(URL,{method:'POST',headers:h,body:JSON.stringify({action,...p})}),d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw new Error(d.error||'Ошибка API интеграции');return d}
const dt=v=>v?new Date(v).toLocaleString('ru-RU'):'Никогда';
window.openApiIntegrations=async function(){openModal('<h2>Интеграции API</h2><section class="card"><p class="muted">Загружаем…</p></section>');try{const d=await call('listIntegrations'),m=document.querySelector('.modal');m.innerHTML=`<button class="modalClose" onclick="closeModal()">×</button><h2>Интеграции API</h2><p class="muted">Подключайте сайты, CRM, ботов, телефонию и другие сервисы к заявкам Business OS.</p><button class="primary wide" onclick="createApiIntegration()">+ Добавить интеграцию</button><div style="height:10px"></div>${(d.integrations||[]).map(x=>`<section class="card"><div class="row"><div><b>${esc(x.name)}</b><div class="muted">${esc(x.slug)}</div></div><span class="apiState ${x.is_active?'on':'off'}">${x.is_active?'Активна':'Отключена'}</span></div><div class="ownerProfileLine"><span>Последнее обращение</span><b>${esc(dt(x.last_used_at))}</b></div><div class="ownerProfileLine"><span>Сопоставление полей</span><b>${Object.keys(x.field_mapping||{}).length?Object.keys(x.field_mapping).length+' полей':'По умолчанию'}</b></div><div class="apiBtns"><button class="secondary" onclick="openApiMapping('${esc(x.id)}')">Настроить поля</button><button class="secondary" onclick="rotateApiKey('${esc(x.id)}','${esc(x.name)}')">Новый ключ</button><button class="secondary" onclick="toggleApiIntegration('${esc(x.id)}',${x.is_active?'false':'true'})">${x.is_active?'Отключить':'Включить'}</button></div></section>`).join('')||'<section class="card"><p class="muted">Интеграций пока нет.</p></section>'}`}catch(e){document.querySelector('.modal').innerHTML=`<button class="modalClose" onclick="closeModal()">×</button><h2>Интеграции API</h2><p class="muted">${esc(e.message)}</p>`}}
window.createApiIntegration=function(){openModal(`<h2>Новая API-интеграция</h2><form id="apiIntForm" class="form"><input name="name" placeholder="Например: Сайт, Telegram, CRM" required><input name="slug" placeholder="Код, необязательно"><button class="primary wide">Создать и получить API-ключ</button><p id="apiIntMsg" class="muted"></p></form>`);document.getElementById('apiIntForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,msg=document.getElementById('apiIntMsg');msg.textContent='Создаём…';try{const d=await call('createIntegration',{name:f.elements.name.value.trim(),slug:f.elements.slug.value.trim()});showKey(d.api_key,d.integration)}catch(x){msg.textContent=x.message}}};
function showKey(key,i){openModal(`<h2>API-ключ создан</h2><section class="card"><b>${esc(i?.name||'Интеграция')}</b><p class="muted">Скопируйте ключ сейчас. После закрытия он больше не показывается.</p><textarea id="apiKeyValue" rows="4" readonly>${esc(key)}</textarea><button class="primary wide" onclick="copyApiKey()">Скопировать ключ</button></section><section class="card"><h3>Подключение</h3><p class="muted">Endpoint</p><input readonly value="${URL}"><p class="muted">Передавайте ключ в заголовке X-API-Key. Для создания или обновления заявки используйте action: upsertOrder и уникальный external_id.</p></section><button class="secondary wide" onclick="openApiIntegrations()">Готово</button>`)}
window.copyApiKey=async function(){const e=document.getElementById('apiKeyValue');try{await navigator.clipboard.writeText(e.value);alert('API-ключ скопирован')}catch(_){e.select();document.execCommand('copy');alert('API-ключ скопирован')}};
window.rotateApiKey=async function(id,name){if(!confirm(`Создать новый API-ключ для «${name}»? Старый перестанет работать.`))return;try{const d=await call('rotateKey',{id});showKey(d.api_key,d.integration)}catch(e){alert(e.message)}};
window.toggleApiIntegration=async function(id,on){try{await call(on?'enableIntegration':'disableIntegration',{id});openApiIntegrations()}catch(e){alert(e.message)}};
window.openApiMapping=async function(id){try{const d=await call('listIntegrations'),i=(d.integrations||[]).find(x=>String(x.id)===String(id));if(!i)throw new Error('Интеграция не найдена');const m=i.field_mapping||{};openModal(`<button class="modalClose" onclick="closeModal()">×</button><h2>Поля · ${esc(i.name)}</h2><p class="muted">Укажите, как называются поля во внешнем приложении. Можно использовать вложенный путь, например <b>customer.name</b>.</p><form id="apiMapForm" class="form apiMapForm">${FIELDS.map(([k,l])=>`<label><span>${esc(l)}</span><small>Business OS: ${esc(k)}</small><input name="${esc(k)}" value="${esc(m[k]||'')}" placeholder="Например: ${esc(k)}"></label>`).join('')}<button class="primary wide" type="submit">Сохранить сопоставление</button><p id="apiMapMsg" class="muted"></p></form><section class="card"><h3>Проверка на примере</h3><p class="muted">Вставьте JSON из внешнего сервиса — Business OS покажет результат преобразования без создания заявки.</p><textarea id="apiMapSample" rows="7" placeholder='{"customer":{"name":"Иван"},"tel":"+7999..."}'></textarea><button class="secondary wide" onclick="testApiMapping('${esc(i.id)}')">Проверить</button><pre id="apiMapPreview" class="apiMapPreview"></pre></section>`);document.getElementById('apiMapForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,msg=document.getElementById('apiMapMsg'),mapping={};FIELDS.forEach(([k])=>{const v=f.elements[k].value.trim();if(v)mapping[k]=v});msg.textContent='Сохраняем…';try{await call('saveMapping',{id:i.id,mapping});msg.textContent='Сопоставление сохранено'}catch(err){msg.textContent=err.message}}}catch(e){alert(e.message)}};
window.testApiMapping=async function(id){const p=document.getElementById('apiMapPreview'),t=document.getElementById('apiMapSample');if(!p||!t)return;try{const sample=JSON.parse(t.value||'{}'),d=await call('testMapping',{id,sample});p.textContent=JSON.stringify(d.mapped||{},null,2)}catch(e){p.textContent='Ошибка: '+e.message}};
const base=window.openOwnerTools;window.openOwnerTools=function(){base();setTimeout(()=>{const sections=[...document.querySelectorAll('.modal section.card')],s=sections.find(x=>x.querySelector('h3')?.textContent.trim()==='Интеграции');if(!s||s.querySelector('.apiIntegrationsBtn'))return;const b=document.createElement('button');b.className='secondary wide ownerToolAction apiIntegrationsBtn';b.innerHTML='<span>Интеграции API</span><b>Управление ›</b>';b.onclick=openApiIntegrations;s.appendChild(b)},0)};
const st=document.createElement('style');st.textContent='.apiState{padding:5px 9px;border-radius:999px;font-size:12px;font-weight:800}.apiState.on{background:rgba(72,199,142,.16);color:#65d89b}.apiState.off{background:rgba(255,255,255,.07);color:var(--muted,#9badc0)}.apiBtns{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}#apiKeyValue{font-family:monospace;word-break:break-all}.apiMapForm label{display:block}.apiMapForm label span{display:block;font-weight:700}.apiMapForm label small{display:block;color:var(--muted,#9badc0);margin:2px 0 5px}.apiMapPreview{white-space:pre-wrap;word-break:break-word;max-height:280px;overflow:auto;background:rgba(0,0,0,.18);border-radius:10px;padding:10px;font-size:12px}';document.head.appendChild(st);
})();

