function session(){try{return sessionStorage.getItem('bos_vk_session_v2')||localStorage.getItem('bos_vk_session_v2')||''}catch(_){return ''}}
async function authHeaders(json=true){const h={};if(json)h['Content-Type']='application/json';let s=session();if(!s&&window.BOS_ENSURE_VK_SESSION){try{await window.BOS_ENSURE_VK_SESSION();s=session()}catch(_){}}if(s)h['X-BOS-Session']=s;let lp=window.BOS_VK_LAUNCH_PARAMS||'';if(!lp&&window.BOS_ENSURE_VK_LAUNCH_PARAMS){try{lp=await window.BOS_ENSURE_VK_LAUNCH_PARAMS()}catch(_){}}if(lp)h['X-VK-Launch-Params']=lp;return h}
function previewMaster(){if(typeof isMasterPreview==='function'&&isMasterPreview()&&typeof liveMasterUser==='function'){const m=liveMasterUser();return m?.vk_user_id||m?.external_id||m?.id||''}return ''}
async function uploadBinary(file,kind,index,orderId,token,onProgress){const fd=new FormData();fd.append('order_id',String(orderId));fd.append('upload_token',token);fd.append('file_kind',kind);fd.append('file_index',String(index));const acting=previewMaster();if(acting)fd.append('acting_master_vk_id',String(acting));fd.append('file',file,file.name||`${kind}.jpg`);onProgress?.();const c=new AbortController(),timer=setTimeout(()=>c.abort(),90000);try{const r=await fetch(FILE_API,{method:'POST',headers:await authHeaders(false),body:fd,signal:c.signal});const d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw new Error(d.error||`Ошибка загрузки файла (${r.status})`);return d.url}catch(e){if(e?.name==='AbortError')throw new Error('Загрузка файла заняла слишком много времени. Проверьте интернет и повторите.');if(/failed to fetch|load failed|networkerror/i.test(String(e?.message||e)))throw new Error('Не удалось передать файл на сервер. Проверьте интернет и повторите.');throw e}finally{clearTimeout(timer)}}
async function finalize(body){const c=new AbortController(),timer=setTimeout(()=>c.abort(),45000);try{const r=await fetch(FINAL_API,{method:'POST',headers:await authHeaders(true),body:JSON.stringify(body),signal:c.signal}),d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw new Error(d.error||`Ошибка сохранения отчёта (${r.status})`);return d}catch(e){if(e?.name==='AbortError')throw new Error('Сервер долго сохраняет отчёт. Повторите отправку.');throw e}finally{clearTimeout(timer)}}
async function submit(e,id){e.preventDefault();const form=e.currentTarget,msg=document.querySelector('#mrMsg');if(state.busy)return;const act=document.querySelector('#mrAct')?.files?.[0],photos=[...(document.querySelector('#mrPhotos')?.files||[])].slice(0,5),extra=document.querySelector('input[name="mrExtra"]:checked')?.value==='true',allDone=document.querySelector('input[name="mrAllDone"]:checked')?.value==='true',unfinished=!allDone,extraDesc=document.querySelector('#mrExtraDesc')?.value?.trim()||'',extraAmount=Number(document.querySelector('#mrExtraAmount')?.value||0),unfinishedDesc=document.querySelector('#mrUnfinishedDesc')?.value?.trim()||'',unfinishedAmount=Number(document.querySelector('#mrUnfinishedAmount')?.value||0);if(!act){msg.textContent='Приложите акт выполненных работ';return}if(!photos.length){msg.textContent='Приложите хотя бы одно фото';return}if(photos.length>5){msg.textContent='Можно загрузить не более 5 фото';return}if(act.size>8*1024*1024){msg.textContent='Акт слишком большой. Максимум 8 МБ';return}if(photos.some(f=>f.size>10*1024*1024)){msg.textContent='Одно из фото больше 10 МБ';return}if(extra&&(!extraDesc||extraAmount<=0)){msg.textContent='Укажите допработы и сумму';return}if(unfinished&&(!unfinishedDesc||unfinishedAmount<=0)){msg.textContent='Укажите, что не выполнено, и стоимость';return}state.busy=true;setBusy(form,true);const token='report_'+Date.now()+'_'+Math.random().toString(36).slice(2);try{msg.textContent='Загружаем акт…';const actUrl=await uploadBinary(act,'act',0,id,token);const photoUrls=[];for(let i=0;i<photos.length;i++){msg.textContent=`Загружаем фото ${i+1} из ${photos.length}…`;photoUrls.push(await uploadBinary(photos[i],'photo',i+1,id,token))}msg.textContent='Сохраняем отчёт…';const body={action:'finalizeMasterReport',order_id:id,upload_token:token,act_url:actUrl,photo_urls:photoUrls,extra_work_done:extra,extra_work_description:extra?extraDesc:'',extra_work_amount:extra?extraAmount:0,uncompleted_work_done:unfinished,uncompleted_work_description:unfinished?unfinishedDesc:'',uncompleted_work_amount:unfinished?unfinishedAmount:0};const acting=previewMaster();if(acting)body.acting_master_vk_id=acting;const d=await finalize(body);if(d.order){const i=state.orders.findIndex(x=>String(x.id)===String(id));if(i>=0)state.orders[i]={...state.orders[i],...d.order}}msg.textContent='Отчёт отправлен';state.busy=false;closeModal();try{await reloadData(true)}catch(_){show('orders')}}catch(err){msg.textContent=err?.message||String(err);setBusy(form,false);state.busy=false}}
// Keep the proven chunked report uploader from report-chunk-upload-v23.js as the submit handler.
// This patch only keeps the mobile/layout class. The legacy report-file-upload endpoint is not deployed.
const old=window.openMasterReportForm;window.openMasterReportForm=function(id){old(id);const form=document.querySelector('#masterReportForm');if(form)form.classList.add('reportFixedV27')};
const st=document.createElement('style');st.textContent=`html,body,#app,main,#content{max-width:100%;overflow-x:hidden}.modalRoot,.modal,.form,.reportCompactForm,.reportFixedV27{max-width:100%;min-width:0;box-sizing:border-box}.reportFixedV27>*{min-width:0;max-width:100%;box-sizing:border-box}.reportFixedV27 input,.reportFixedV27 textarea,.reportFixedV27 select,.reportFixedV27 button{max-width:100%;min-width:0;box-sizing:border-box}.reportFixedV27 input[type=file]{display:block;width:100%;min-width:0;overflow:hidden;padding:8px;font-size:13px}.reportFixedV27 .reportQuestion{width:100%;min-width:0;box-sizing:border-box}.reportFixedV27 .reportChoices{flex:0 0 auto;min-width:116px}.reportFixedV27 .reportChoice{min-width:0}.reportFixedV27 .reportChoice span{min-width:48px;max-width:80px;box-sizing:border-box}.reportFixedV27 .reportConditional{width:100%;max-width:100%;grid-template-columns:minmax(0,1fr) minmax(100px,130px);box-sizing:border-box}.reportFixedV27 .reportConditional input{width:100%;min-width:0;box-sizing:border-box}.reportFixedV27 #mrMsg{overflow-wrap:anywhere;word-break:break-word}@media(max-width:560px){.modal{width:calc(100vw - 24px)!important;max-width:calc(100vw - 24px)!important;margin-left:auto!important;margin-right:auto!important;overflow-x:hidden!important}.reportFixedV27 .reportQuestion{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:8px}.reportFixedV27 .reportChoices{width:auto;min-width:112px}.reportFixedV27 .reportConditional{grid-template-columns:1fr}.reportFixedV27 input[type=file]{font-size:12px}}`;document.head.appendChild(st);
