// Source: mandatory-auth-v29.js
(()=>{
  const BASE='https://business-os-api-gateway.netlify.app/api/proxy/';
  const MINI=BASE+'mini-app-api';
  const VK=BASE+'vk-session-api';
  const PASS=BASE+'password-session-api';
  const INVITE=BASE+'staff-invite-api';
  const KEY='bos_vk_session_v2';
  const gate=document.getElementById('authGate');
  const body=document.body;
  const forceVk=new URLSearchParams(location.search).has('force_vk_auth');
  let vkSessionPromise=null;
  let validatedBootstrap=null;
  let bootPromise=null;
  let waitingForNetwork=false;

  function getSession(){try{return sessionStorage.getItem(KEY)||localStorage.getItem(KEY)||''}catch(_){return ''}}
  function setSession(v){if(!v)return;try{sessionStorage.setItem(KEY,v);localStorage.setItem(KEY,v)}catch(_){}}
  function clearSession(){validatedBootstrap=null;try{sessionStorage.removeItem(KEY);localStorage.removeItem(KEY)}catch(_){}}
  function escs(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
  function showGate(html){if(!gate)return;gate.innerHTML=`<div class="authGateCard">${html}</div>`;gate.style.display='flex';body.classList.remove('bos-auth-ok')}
  function unlock(){if(gate)gate.style.display='none';body.classList.add('bos-auth-ok');window.dispatchEvent(new Event('bos:auth-ready'))}

  async function post(url,payload,headers={}){
    const controller=new AbortController();
    const timer=setTimeout(()=>controller.abort(),20000);
    try{
      const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json',...headers},body:JSON.stringify(payload),signal:controller.signal});
      const d=await r.json().catch(e=>{if(e?.name==='AbortError')throw e;if(r.ok)throw new Error('Сервер вернул некорректный ответ. Повторите попытку.');return {}});
      if(!r.ok||d?.ok===false){const e=new Error(d?.error||('Ошибка сервера '+r.status));e.status=r.status;e.data=d;throw e}
      return d;
    }catch(e){
      if(e?.name==='AbortError')throw new Error('Сервер не ответил. Повторите попытку.');
      if(/load failed|failed to fetch|networkerror|network request failed/i.test(String(e?.message||'')))throw new Error('Не удалось связаться с сервером. Проверьте интернет и повторите попытку.');
      throw e;
    }finally{clearTimeout(timer)}
  }

  function signed(raw){
    raw=String(raw||'').replace(/^\?/,'');
    const p=new URLSearchParams(raw);
    return p.has('vk_app_id')&&p.has('vk_user_id')&&p.has('sign')?raw:'';
  }
  function launchFromPage(){
    let raw=signed(location.search);if(raw)return raw;
    const h=String(location.hash||'');
    raw=signed(h.includes('?')?h.slice(h.indexOf('?')+1):h.replace(/^#/,''));
    return raw;
  }
  function fromObject(obj){
    const src=obj?.launch_params||obj;if(!src)return '';
    const p=new URLSearchParams();
    Object.keys(src).filter(k=>k==='sign'||k.startsWith('vk_')).sort().forEach(k=>{if(src[k]!=null)p.set(k,String(src[k]))});
    return signed(p.toString());
  }
  async function waitForBridge(){
    if(window.vkBridge?.send)return true;
    const ready=window.BOS_VK_BRIDGE_READY;
    if(!ready||typeof ready.then!=='function')return false;
    let timer;
    try{return !!(await Promise.race([ready,new Promise(resolve=>{timer=setTimeout(()=>resolve(false),8000)})]))}
    catch(_){return false}
    finally{clearTimeout(timer)}
  }
  async function getVkLaunch(){
    const immediate=launchFromPage();if(immediate)return immediate;
    if(!window.vkBridge?.send)await waitForBridge();
    if(!window.vkBridge?.send)return '';
    try{
      let timer;
      try{return await Promise.race([(async()=>{
        await window.vkBridge.send('VKWebAppInit',{}).catch(()=>{});
        return fromObject(await window.vkBridge.send('VKWebAppGetLaunchParams',{}));
      })(),new Promise(resolve=>{timer=setTimeout(()=>resolve(''),6000)})]);}
      finally{clearTimeout(timer)}
    }catch(_){return ''}
  }
  function isVkLaunch(){return forceVk||!!launchFromPage()}

  async function validate(){
    const session=getSession();if(!session)return false;
    try{
      const d=await post(MINI,{action:'bootstrap'},{'X-BOS-Session':session});
      if(!d?.user?.role)return false;
      validatedBootstrap={session,data:d};
      return true;
    }catch(e){if(e?.status===401){clearSession();return false}throw e}
  }
  async function vkSession(){
    const existing=getSession();if(existing)return {ok:true,session_token:existing};
    const launch=await getVkLaunch();
    if(!launch)throw new Error('Не удалось получить параметры запуска VK. Закройте приложение и откройте его заново через ВКонтакте.');
    const d=await post(VK,{launch_params:launch});
    if(d?.session_token)setSession(d.session_token);
    if(d?.registration_required){inviteScreen();return {ok:true,registration_required:true,session_token:getSession()}}
    if(!d?.session_token)throw new Error('VK не подтвердил вход.');
    return d;
  }
  async function ensureVkSession(){
    const existing=getSession();if(existing)return {ok:true,session_token:existing};
    if(!vkSessionPromise)vkSessionPromise=vkSession().finally(()=>{vkSessionPromise=null});
    return await vkSessionPromise;
  }

  async function sessionApi(action,payload={}){
    const session=getSession();
    if(!session)throw new Error('Требуется вход');
    if(action==='bootstrap'&&validatedBootstrap?.session===session&&!Object.keys(payload||{}).length){
      const d=validatedBootstrap.data;
      validatedBootstrap=null;
      return d;
    }
    return post(MINI,{action,...payload},{'X-BOS-Session':session});
  }
  async function inviteApi(action,payload={}){
    const session=getSession();
    if(!session)throw new Error('Требуется подтверждённый вход VK');
    return post(INVITE,{action,...payload},{'X-BOS-Session':session});
  }
  window.BOS_POST=post;
  window.api=sessionApi;try{api=sessionApi}catch(_){ }
  window.BOS_STORE_SESSION=setSession;
  window.BOS_AUTH_HEADERS=async()=>({'Content-Type':'application/json','X-BOS-Session':getSession()});
  window.BOS_ENSURE_VK_LAUNCH_PARAMS=getVkLaunch;
  window.BOS_ENSURE_VK_SESSION=ensureVkSession;

  async function loadApp(){
    if(typeof reloadData!=='function')throw new Error('Приложение не готово к запуску');
    await reloadData(false);
    if(!state?.user?.role)throw new Error('Не удалось определить роль сотрудника');
    // A cached/fast bootstrap can finish before the final deferred loader script.
    if(typeof window.BOS_LOAD_ROLE_MODULES!=='function'&&document.readyState!=='complete')await new Promise(resolve=>document.addEventListener('DOMContentLoaded',resolve,{once:true}));
    if(typeof window.BOS_LOAD_ROLE_MODULES==='function')await window.BOS_LOAD_ROLE_MODULES(state.user.role);
    try{if(typeof updateNavForRole==='function')updateNavForRole()}catch(_){}
    try{if(typeof window.show==='function')window.show(state.page||'home')}catch(_){}
    unlock();
  }

  function passwordScreen(msg=''){
    showGate(`<div class="authLogo">Домашний мастер</div><h1>Вход по логину</h1>${msg?`<p class="authError">${escs(msg)}</p>`:'<p class="muted">Вход с компьютера</p>'}<form id="simplePassForm" class="form"><input name="login" autocomplete="username" placeholder="Логин" required><input name="password" type="password" autocomplete="current-password" placeholder="Пароль" required><button class="primary wide" type="submit">Войти</button><p id="simplePassMsg" class="muted"></p></form>`);
    document.getElementById('simplePassForm').onsubmit=async e=>{
      e.preventDefault();const f=e.currentTarget,m=document.getElementById('simplePassMsg');if(f.dataset.pending)return;f.dataset.pending='1';const btn=f.querySelector('button');btn.disabled=true;m.textContent='Проверяем…';
      try{const d=await post(PASS,{action:'login',login:f.elements.login.value,password:f.elements.password.value});if(!d?.session_token)throw new Error('Сервер не выдал сессию');setSession(d.session_token);await loadApp()}catch(err){m.textContent=err.message}finally{delete f.dataset.pending;btn.disabled=false}
    };
  }
  function retryVkScreen(msg){
    showGate(`<div class="authLogo">Домашний мастер</div><h1>Не удалось войти</h1><p class="authError">${escs(msg)}</p><button id="simpleVkRetry" class="primary wide">Повторить вход через VK</button>`);
    document.getElementById('simpleVkRetry').onclick=boot;
  }
  function inviteScreen(){
    showGate(`<div class="authLogo">Домашний мастер</div><h1>Вход по приглашению</h1><p class="muted">Введите одноразовый код, который выдал владелец. Код действует 1 час.</p><form id="simpleInviteForm" class="form"><input name="code" type="text" inputmode="text" autocomplete="one-time-code" autocapitalize="characters" maxlength="14" placeholder="Код приглашения" required><button class="primary wide" type="submit">Войти</button><p id="simpleInviteMsg" class="muted"></p></form>`);
    document.getElementById('simpleInviteForm').onsubmit=async e=>{
      e.preventDefault();const f=e.currentTarget,m=document.getElementById('simpleInviteMsg');if(f.dataset.pending)return;f.dataset.pending='1';const btn=f.querySelector('button');btn.disabled=true;m.textContent='Проверяем код…';
      try{const d=await inviteApi('redeem',{code:f.elements.code.value});if(!d?.user?.role)throw new Error('Не удалось привязать сотрудника');await loadApp()}catch(err){m.textContent=err.message}finally{delete f.dataset.pending;btn.disabled=false}
    };
  }

  function recoveryScreen(error){
    waitingForNetwork=true;
    showGate(`<div class="authLogo">Домашний мастер</div><h1>Не удалось загрузить приложение</h1><p class="authError">${escs(error?.message||'Проверьте подключение к интернету.')}</p><button id="simpleBootRetry" class="primary wide">Повторить</button>`);
    document.getElementById('simpleBootRetry').onclick=boot;
  }
  async function runBoot(){
    waitingForNetwork=false;
    showGate(`<div class="authLogo">Домашний мастер</div><h1>Проверяем вход…</h1><p class="muted">Пожалуйста, подождите.</p>`);
    if(await validate())return await loadApp();
    if(!isVkLaunch())return passwordScreen();
    try{const r=await ensureVkSession();if(r?.registration_required)return;await loadApp()}catch(e){retryVkScreen(e.message)}
  }
  function boot(){
    if(!bootPromise)bootPromise=runBoot().catch(recoveryScreen).finally(()=>{bootPromise=null});
    return bootPromise;
  }
  window.addEventListener('online',()=>{if(waitingForNetwork)boot()});
  window.BOS_FORCE_AUTH_SCREEN=()=>{clearSession();isVkLaunch()?boot():passwordScreen()};
  boot();
})();

