const roleLabel=r=>({owner:'Владелец',manager:'Руководитель',dispatcher:'Диспетчер',master:'Мастер'}[r]||r||'Сотрудник');
function actorRole(){if(window.BOS_IS_MANAGER_PREVIEW?.())return'manager';if(typeof isDispatcherPreview==='function'&&isDispatcherPreview())return'dispatcher';return String(state.user?.role||'');}
function canManage(target){const a=actorRole(),t=String(target?.role||'');if(t==='owner')return false;if(a==='owner')return ['manager','dispatcher','master'].includes(t);if(a==='manager')return ['dispatcher','master'].includes(t);if(a==='dispatcher')return t==='master';return false;}
function uid(u){return String(u?.vk_user_id||u?.external_id||u?.id||'');}
function active(u){return String(u?.is_active??u?.active??true)!=='false';}
if(typeof pages!=='undefined'&&pages.home){const baseHome=pages.home;pages.home=function(){let html=baseHome();if(actorRole()!=='dispatcher')return html;html=String(html).replace(/Расчёт зарплаты/g,'Зарплата').replace(/<p class="muted"[^>]*>Расчёт:[\s\S]*?<\/p>/g,'');return html;};}
const baseProfile=window.openOwnerProfile;window.openOwnerProfile=function(){baseProfile?.();if(actorRole()!=='dispatcher')return;setTimeout(()=>{document.querySelectorAll('#modalRoot .modal p').forEach(p=>{if(String(p.textContent||'').trim().startsWith('Расчёт:'))p.remove();});},0);};
function ids(x){return [x?.id,x?.staff_id,x?.master_staff_id,x?.vk_user_id,x?.user_id,x?.external_id].filter(Boolean).map(String);}
function sameMaster(a,b){const s=new Set(ids(a));return ids(b).some(x=>s.has(x));}
function ordersFor(m,date){return (state.orders||[]).filter(o=>String(o.scheduled_date||'').slice(0,10)===date&&String(o.status||'')!=='Отменена'&&(ids(m).includes(String(o.master_vk_id||o.master_id||o.master_staff_id||''))||String(o.master_name||'')===String(m.full_name||'')));}
function scheduleFor(m,date){return (state.masterSchedule||[]).find(r=>String(r.work_date||r.date||'').slice(0,10)===date&&sameMaster(m,r));}
window.openStaffCalendarDay=function(date){const masters=(state.masters||[]).filter(active);const rows=masters.map(m=>{const r=scheduleFor(m,date),working=!!r&&r.is_working!==false&&String(r.is_working)!=='false',os=ordersFor(m,date);if(!working&&!os.length)return'';return `<section class="card"><div class="row"><div><b>${esc(m.full_name||'Мастер')}</b><div class="muted">${working?`${esc(String(r.work_start||'').slice(0,5)||'—')}–${esc(String(r.work_end||'').slice(0,5)||'—')}`:'Выходной'}</div></div><span class="status info">${os.length} заяв.</span></div>${os.map(o=>`<button class="secondary wide" style="margin-top:7px;text-align:left" onclick="closeModal();openOrder('${esc(o.id)}')">${esc(String(o.scheduled_time||o.time_slot||'').slice(0,5)||'—')} · ${esc(o.client||o.work||'Заявка')}</button>`).join('')}</section>`;}).join('');openModal(`<h2>${esc(new Date(date+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'}))}</h2><p class="muted">Работающие мастера и загрузка по заявкам</p>${rows||'<p class="muted">На этот день нет работающих мастеров и заявок.</p>'}`);};
if(typeof window.selectDispatcherCalendarDate==='function'){window.selectDispatcherCalendarDate=function(date){window.openStaffCalendarDay(date);};}
const baseEmployeeProfile=window.openEmployeeProfile;window.openEmployeeProfile=function(id){baseEmployeeProfile?.(id);const u=(state.users||[]).find(x=>uid(x)===String(id));if(!u||!canManage(u))return;setTimeout(()=>{const modal=document.querySelector('#modalRoot .modal');if(!modal||modal.querySelector('.staffAdminActions'))return;const box=document.createElement('section');box.className='card staffAdminActions';box.innerHTML=`<h3>Управление сотрудником</h3><p class="muted">Отключение сохраняет историю заявок, выплат и отчётов.</p><button class="secondary wide" data-disable-staff="${esc(uid(u))}">Отключить профиль</button>`;const back=[...modal.querySelectorAll('button')].find(b=>String(b.textContent||'').includes('К списку сотрудников'));if(back)modal.insertBefore(box,back);else modal.appendChild(box);box.querySelector('[data-disable-staff]').onclick=()=>window.disableStaffProfile(uid(u));},0);};
window.disableStaffProfile=async function(id){const u=(state.users||[]).find(x=>uid(x)===String(id));if(!u||!canManage(u))return;const name=u.full_name||u.name||'сотрудника';if(!confirm(`Отключить профиль «${name}»? История сохранится.`))return;try{const d=await api('updateEmployee',{vk_user_id:uid(u),is_active:false});if(!d?.ok)throw new Error(d?.error||'Не удалось отключить профиль');const fresh=await api('bootstrap');if(!fresh?.ok)throw new Error(fresh?.error||'Не удалось проверить отключение');const stillActive=(fresh.users||[]).some(x=>uid(x)===uid(u));if(stillActive)throw new Error('Сервер не подтвердил отключение сотрудника');state.users=fresh.users||[];state.masters=fresh.masters||[];state.masterSchedule=fresh.masterSchedule||state.masterSchedule||[];closeModal();show('team');}catch(e){openModal(`<h2>Не удалось отключить профиль</h2><p class="muted">${esc(e?.message||'Ошибка сервера')}</p>`);}};
