const reportOpenBase=window.openMasterReportForm;if(typeof reportOpenBase==='function')window.openMasterReportForm=function(id){reportOpenBase(id);const form=document.querySelector('#masterReportForm'),msg=document.querySelector('#mrMsg');if(!form)return;const original=form.onsubmit;form.onsubmit=async function(e){if(msg)msg.textContent='Подготавливаем отчёт…';try{return await original.call(this,e)}catch(err){e.preventDefault();if(msg)msg.textContent=err?.message||'Не удалось отправить отчёт. Повторите.';state.busy=false;try{setBusy(form,false)}catch(_){}}}};
const st=document.createElement('style');st.textContent='.masterHomeWeek{margin-top:0}.masterWeekDays{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px;margin-top:12px}.masterWeekDay{padding:8px 4px!important;min-height:66px;display:flex;flex-direction:column;align-items:center;gap:3px;border-radius:10px;border:1px solid transparent;color:inherit}.masterWeekDay.workDay{background:rgba(51,160,93,.18);border-color:rgba(72,190,116,.55)}.masterWeekDay.offDay{background:rgba(130,140,150,.12);border-color:rgba(150,160,170,.22)}.masterWeekDay b{font-size:11px;text-transform:capitalize}.masterWeekDay span{font-size:16px;font-weight:800}.masterWeekDay small{font-size:9px;color:var(--muted,#8ea0b5);text-align:center}.bosSchedulePresets.compact{display:flex;gap:7px;align-items:center;justify-content:flex-end;flex-wrap:wrap;margin-left:auto}.bosMiniPreset{display:inline-flex;align-items:center;gap:4px;font-size:11px;color:var(--muted,#8ea0b5);white-space:nowrap;cursor:pointer;padding:4px 7px;border-radius:999px;border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.035)}.bosMiniPreset.active{background:rgba(51,160,93,.18);border-color:rgba(72,190,116,.55);color:#b9efc9}.bosMiniPreset input{width:14px;height:14px;margin:0}.bosCalDay.bosWorkGreen{background:rgba(51,160,93,.18)!important;border-color:rgba(72,190,116,.55)!important}.bosCalDay.bosOffGray{background:rgba(130,140,150,.10)!important;border-color:rgba(150,160,170,.20)!important}.bosCalDay.selected{outline:2px solid #58b2ff!important;outline-offset:1px}@media(max-width:560px){.masterWeekDays{overflow-x:auto;grid-template-columns:repeat(7,minmax(64px,1fr))}.bosSchedulePresets.compact{width:100%;justify-content:flex-start;margin-top:8px}}';document.head.appendChild(st);
