const payout=o=>{const raw=o?.amount;if(raw!==null&&raw!==undefined&&raw!==''){const amount=Number(raw);if(Number.isFinite(amount))return amount*0.85*0.65}const stored=Number(o?.master_payout||0);return Number.isFinite(stored)?stored:0};
const workLines=o=>String(o?.work||'Работа не указана').split(/\n+/).map(x=>x.trim()).filter(Boolean);
function salaryTotal(){if(typeof ownPayoutTotal==='function'){try{const base=Number(ownPayoutTotal()),extra=typeof ownExtraTotal==='function'?Number(ownExtraTotal()):0;if(Number.isFinite(base)&&Number.isFinite(extra))return Math.max(0,base+extra)}catch(_){}}return Math.max(0,own().filter(o=>String(o.status||'')==='Выполнена').reduce((sum,o)=>sum+payout(o)+Number(o.extra_work_amount||0),0))}
function normalizeSalary(root){const expected=money(salaryTotal());for(const el of root.querySelectorAll('.masterKpi,.masterSalarySummary,.metric,.card')){if(!(el.textContent||'').includes('Общая зарплата'))continue;const strong=el.querySelector('strong,b');if(strong&&strong.textContent!==expected)strong.textContent=expected}}
function compactCard(o){const lines=workLines(o),shown=lines.slice(0,2);return `<button class="masterCompactOrder masterUpcomingCompact" onclick="openOrder('${esc(o.id)}')"><div class="masterCompactTop"><b>№ ${esc(no(o))}</b><span>${esc(dt(o))}</span></div><div class="masterCompactLine"><b>${esc(o.client||'Клиент не указан')}</b><span>${money(payout(o))}</span></div><div class="masterCompactAddress">${esc(o.address||'Адрес не указан')}</div><div class="masterCompactWork">${shown.map(x=>esc(x)).join('<br>')}${lines.length>2?`<br><span class="muted">+ ещё ${lines.length-2}</span>`:''}</div></button>`}
