function replaceUpcoming(){if(!masterMode()||state?.page!=='home')return;const root=document.getElementById('content');if(!root)return;root.querySelectorAll('.eyebrow').forEach(el=>{if((el.textContent||'').toUpperCase().includes('КАБИНЕТ МАСТЕРА'))el.remove()});const h=[...root.querySelectorAll('h2,h3')].find(x=>(x.textContent||'').trim()==='Ближайшие заявки');if(!h)return;const section=h.closest('section')||h.parentElement;if(!section)return;const sig=JSON.stringify(upcomingGroups().map(([d,list])=>[d,list.map(o=>[o.id,payout(o),o.scheduled_time||o.time_slot,workSummary(o)])]));if(section.dataset.bosMasterUpcomingSig===sig)return;section.dataset.bosMasterUpcomingSig=sig;section.innerHTML=`<div class="masterSectionTitle"><h3 style="margin:0">Ближайшие заявки</h3><button class="secondary" onclick="show('orders')">Все</button></div>${upcomingHtml()}`}
function stripStaffManagement(){if(!masterMode())return;document.querySelectorAll('h1,h2,h3,h4,b,strong,div').forEach(el=>{if((el.textContent||'').trim().toLowerCase()!=='управление сотрудниками')return;const block=el.closest('section,.card');if(block)block.remove();else el.remove()})}
function ensureCabinetInProfile(){if(!masterMode()||state?.page!=='team')return;const root=document.getElementById('content');if(!root)return;stripStaffManagement();if(!root.querySelector('.bosMasterCabinetProfileTitle')){const title=document.createElement('div');title.className='bosMasterCabinetProfileTitle eyebrow';title.textContent='КАБИНЕТ МАСТЕРА';root.prepend(title)}}
function scheduleRows(){return (state?.masterSchedule||[]).filter(r=>mineSchedule(r)&&truthy(r?.is_working)&&dateOnly(r?.work_date||r?.date)).sort((a,b)=>dateOnly(a.work_date||a.date).localeCompare(dateOnly(b.work_date||b.date)))}
function placeText(){const u=liveUser(),m=masterRow();return [u?.city||m?.city,m?.district||m?.area||m?.work_area||u?.district||u?.area||u?.work_area].filter(Boolean).join(' · ')||'Не указано'}
function scheduleSummaryData(){const rows=scheduleRows(),future=rows.filter(r=>dateOnly(r.work_date||r.date)>=today()).slice(0,14),src=future.length?future:rows.slice(0,14);const timeCounts={};src.forEach(r=>{const k=`${String(r.work_start||'').slice(0,5)}–${String(r.work_end||'').slice(0,5)}`;timeCounts[k]=(timeCounts[k]||0)+1});return{src,place:placeText(),time:Object.entries(timeCounts).sort((a,b)=>b[1]-a[1])[0]?.[0]||'—'}}
function scheduleSummaryHtml(data=scheduleSummaryData()){const {src,place,time}=data;if(!src.length)return '<section class="card bosMasterSavedSchedule"><h3>Сохранённый график</h3><p class="muted">График ещё не сохранён.</p></section>';return `<section class="card bosMasterSavedSchedule"><div class="row"><div><h3 style="margin:0">Сохранённый график</h3><div class="muted">После сохранения выбранные дни остаются видны здесь</div></div></div><div class="bosMasterScheduleMeta"><span><small>Где</small><b>${esc(place)}</b></span><span><small>Время</small><b>${esc(time)}</b></span></div><div class="bosMasterScheduleDays">${src.map(r=>{const d=dateOnly(r.work_date||r.date);return `<span><b>${esc(dayLabel(d))}</b><small>${esc(d.slice(8,10)+'.'+d.slice(5,7))}</small></span>`}).join('')}</div></section>`}
function ensureScheduleSummary(){if(!masterMode()||state?.page!=='dispatch')return;const root=document.getElementById('content');if(!root)return;const data=scheduleSummaryData(),sig=JSON.stringify({place:data.place,time:data.time,rows:data.src.map(r=>[dateOnly(r.work_date||r.date),String(r.work_start||''),String(r.work_end||'')])}),current=root.querySelector('.bosMasterSavedSchedule');if(current?.dataset.bosScheduleSig===sig)return;const wrap=document.createElement('div');wrap.innerHTML=scheduleSummaryHtml(data);const next=wrap.firstElementChild;next.dataset.bosScheduleSig=sig;if(current)current.replaceWith(next);else root.prepend(next)}
const openBase=window.openOrder;
window.openOrder=function(id){const out=openBase?.apply(this,arguments);if(!masterMode())return out;const add=()=>{const o=(state?.orders||[]).find(x=>String(x.id)===String(id));if(!o||['Выполнена','Отменена'].includes(String(o.status||'')))return;const modal=document.querySelector('#modalRoot .modal')||document.querySelector('#modalRoot');if(!modal||modal.querySelector('.bosMasterReportAction'))return;if(typeof window.openMasterReportForm!=='function')return;const btn=document.createElement('button');btn.type='button';btn.className='primary wide bosMasterReportAction';btn.textContent='Отчитаться по заявке';btn.onclick=()=>window.openMasterReportForm(id);modal.appendChild(btn)};setTimeout(add,0);setTimeout(add,60);return out};
const saveCompact=window.saveCompactMasterSchedule;
if(typeof saveCompact==='function')window.saveCompactMasterSchedule=async function(){const out=await saveCompact.apply(this,arguments);setTimeout(()=>{if(masterMode()){try{show('dispatch')}catch(_){ensureScheduleSummary()}}},0);return out};
function postProcess(){if(!masterMode())return;stripStaffManagement();replaceUpcoming();ensureCabinetInProfile()}
const showBase=window.show;
window.show=function(){const out=showBase.apply(this,arguments);setTimeout(()=>{postProcess();ensureScheduleSummary()},0);setTimeout(()=>{postProcess();ensureScheduleSummary()},80);return out};
let postQueued=false;
function queuePost(){if(postQueued||!masterMode())return;postQueued=true;requestAnimationFrame(()=>{postQueued=false;postProcess()})}
const obs=new MutationObserver(queuePost),content=document.getElementById('content');if(content)obs.observe(content,{childList:true,subtree:true});
const style=document.createElement('style');style.textContent=`.bosMasterUpcomingDays{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(210px,1fr);gap:8px;overflow-x:auto;padding:4px 0 2px;scrollbar-width:none}.bosMasterUpcomingDays::-webkit-scrollbar{display:none}.bosMasterUpcomingDay{border:1px solid rgba(255,255,255,.09);background:rgba(255,255,255,.025);border-radius:12px;padding:8px;min-width:0}.bosMasterUpcomingDayHead{display:flex;align-items:baseline;justify-content:space-between;gap:8px;margin-bottom:6px}.bosMasterUpcomingDayHead b{font-size:12px;text-transform:capitalize;white-space:nowrap}.bosMasterUpcomingDayHead span{font-size:10px;color:var(--muted,#91a3b7);white-space:nowrap}.bosMasterUpcomingCard{width:100%;display:block;text-align:left;padding:9px 10px;margin-top:5px;border-radius:9px;border:1px solid rgba(255,255,255,.07);background:var(--card,#111d2b);color:inherit;overflow:hidden}.bosMasterUpcomingCard .bosUpcomingNo,.bosMasterUpcomingCard .bosUpcomingWork,.bosMasterUpcomingCard .bosUpcomingMeta{display:block;max-width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.bosMasterUpcomingCard .bosUpcomingNo{font-size:13px;font-weight:800;line-height:1.25}.bosMasterUpcomingCard .bosUpcomingWork{font-size:11.5px;line-height:1.3;margin-top:4px;color:var(--text,#eef4fb)}.bosMasterUpcomingCard .bosUpcomingMeta{font-size:10.5px;line-height:1.25;margin-top:5px;color:var(--muted,#91a3b7)}.bosMasterReportAction{margin-top:12px!important}.bosMasterCabinetProfileTitle{margin:2px 0 10px}.bosMasterSavedSchedule{margin-bottom:10px}.bosMasterScheduleMeta{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:10px}.bosMasterScheduleMeta span{padding:8px;border:1px solid rgba(255,255,255,.07);border-radius:10px;background:rgba(255,255,255,.025)}.bosMasterScheduleMeta small{display:block;color:var(--muted,#91a3b7);font-size:10px;margin-bottom:3px}.bosMasterScheduleMeta b{font-size:12px}.bosMasterScheduleDays{display:flex;gap:6px;overflow-x:auto;margin-top:8px;scrollbar-width:none}.bosMasterScheduleDays::-webkit-scrollbar{display:none}.bosMasterScheduleDays span{min-width:64px;padding:7px 6px;text-align:center;border-radius:9px;border:1px solid rgba(72,190,116,.35);background:rgba(51,160,93,.12)}.bosMasterScheduleDays b,.bosMasterScheduleDays small{display:block}.bosMasterScheduleDays b{font-size:11px}.bosMasterScheduleDays small{font-size:10px;color:var(--muted,#91a3b7);margin-top:2px}@media(max-width:520px){.bosMasterUpcomingDays{grid-auto-columns:minmax(210px,72vw)}.bosMasterScheduleMeta{grid-template-columns:1fr}}`;document.head.appendChild(style);
setTimeout(()=>{postProcess();ensureScheduleSummary()},0);
