// Source: dispatcher-mobile-dispatch-v107.js
(()=>{
'use strict';
if(window.BOS_DISPATCHER_MOBILE_DISPATCH_V107)return;window.BOS_DISPATCHER_MOBILE_DISPATCH_V107=true;
const MOBILE_MAX=760;
let selectedDate=localToday();
let wasMobile=window.innerWidth<=MOBILE_MAX;

function dispatcherMode(){return (typeof isDispatcherPreview==='function'&&isDispatcherPreview())||String(state?.user?.role||'')==='dispatcher'}
function mobileMode(){return window.innerWidth<=MOBILE_MAX}
function pad(n){return String(n).padStart(2,'0')}
function localToday(){const d=new Date();return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`}
function dateOnly(v){return String(v||'').slice(0,10)}
function hm(v){return String(v||'').slice(0,5)}
function active(o){return !['Выполнена','Отменена'].includes(String(o?.status||''))}
function safe(v){return typeof esc==='function'?esc(v):String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function normalizePhone(value){let p=String(value||'').trim().replace(/[^\d+]/g,'');if(/^8\d{10}$/.test(p))p='+7'+p.slice(1);else if(/^\d{10}$/.test(p))p='+7'+p;return p}
function addDays(date,n){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`}
function dayName(date,opts={weekday:'short',day:'numeric'}){try{return new Date(date+'T12:00:00').toLocaleDateString('ru-RU',opts)}catch(_){return date}}
function masterIds(x){return [x?.id,x?.staff_id,x?.master_staff_id,x?.master_id,x?.vk_user_id,x?.user_id,x?.external_id].filter(Boolean).map(String)}
function sameMaster(a,b){const aa=new Set(masterIds(a));return masterIds(b).some(x=>aa.has(x))||String(a?.full_name||a?.name||'')===String(b?.full_name||b?.name||'')}
function allMasters(){const list=[...(state?.masters||[]),...(state?.users||[]).filter(u=>String(u?.role)==='master')],out=[];for(const m of list){if(!m)continue;if(out.some(x=>sameMaster(x,m)))continue;out.push(m)}return out}
function orderMasterKey(o){return String(o?.master_staff_id||o?.master_vk_id||o?.master_id||o?.master_name||'')}
function assignedTo(o,m){const key=orderMasterKey(o);return !!key&&(masterIds(m).includes(key)||String(o?.master_name||'')===String(m?.full_name||m?.name||''))}
function isUnassigned(o){return active(o)&&!orderMasterKey(o)}
function dayOrders(){return (state?.orders||[]).filter(o=>active(o)&&dateOnly(o.scheduled_date)===selectedDate)}
function scheduleFor(m){return (state?.masterSchedule||[]).find(r=>dateOnly(r?.work_date||r?.date)===selectedDate&&sameMaster(m,r))}
function isWorking(r){return !!r&&r.is_working!==false&&String(r.is_working)!=='false'}
function scheduleText(m){const r=scheduleFor(m);if(!r)return'График не задан';if(!isWorking(r))return'Выходной';const a=hm(r.work_start),b=hm(r.work_end);return a&&b?`${a}–${b}`:'Рабочий день'}
function toMinutes(v){const m=String(v||'').match(/^(\d{1,2}):(\d{2})/);return m?Number(m[1])*60+Number(m[2]):null}
function interval(o){const slot=String(o?.time_slot||'').replace(/-/g,'–');if(slot.includes('–')){const [a,b]=slot.split('–').map(x=>toMinutes(x.trim()));if(a!==null&&b!==null&&b>a)return[a,b]}const start=toMinutes(o?.scheduled_time);return start===null?null:[start,start+60]}
function conflictIds(orders){const ids=new Set();for(let i=0;i<orders.length;i++){const a=orders[i],ia=interval(a),ka=orderMasterKey(a);if(!ia||!ka)continue;for(let j=i+1;j<orders.length;j++){const b=orders[j],ib=interval(b),kb=orderMasterKey(b);if(!ib||ka!==kb)continue;if(ia[0]<ib[1]&&ib[0]<ia[1]){ids.add(String(a.id));ids.add(String(b.id))}}}return ids}
function timeText(o){return hm(o?.scheduled_time)||String(o?.time_slot||'').split(/[–-]/)[0].trim()||'Без времени'}
function sortOrders(list){return [...list].sort((a,b)=>timeText(a).localeCompare(timeText(b),'ru',{numeric:true})||String(a.id).localeCompare(String(b.id),'ru',{numeric:true}))}
function statusChip(o){const s=String(o?.status||'В работе');return `<span class="dmv2Status">${safe(s)}</span>`}
function actions(o,{assign=false}={}){const phone=normalizePhone(o?.phone||o?.client_phone);return `<div class="dmv2Actions">${phone?`<a class="secondary" href="tel:${safe(phone)}" onclick="event.stopPropagation()">Позвонить</a>`:''}${assign?`<button class="secondary" type="button" onclick="event.stopPropagation();dmv2Assign('${safe(o.id)}')">Назначить</button>`:''}<button class="secondary" type="button" onclick="event.stopPropagation();dmv2Move('${safe(o.id)}')">Перенести</button><button class="secondary" type="button" onclick="event.stopPropagation();openOrder('${safe(o.id)}')">Открыть</button></div>`}
function orderCard(o,conflicts,{assign=false}={}){const conflict=conflicts.has(String(o.id));return `<section class="card dmv2Order ${conflict?'conflict':''}" onclick="openOrder('${safe(o.id)}')"><div class="dmv2OrderTop"><div><b>${safe(timeText(o))}</b><span>№ ${safe(o.id)}</span></div>${conflict?'<span class="dmv2Alert">Конфликт</span>':statusChip(o)}</div><h3>${safe(o.work||'Заявка')}</h3><p class="dmv2Client">${safe(o.client||'Клиент')}</p><p class="muted dmv2Address">${safe(o.address||'Адрес не указан')}</p>${!assign&&o.master_name?`<p class="dmv2MasterName">${safe(o.master_name)}</p>`:''}${actions(o,{assign})}</section>`}
function dayStrip(){let html='';for(let i=-3;i<=3;i++){const date=addDays(selectedDate,i),activeDay=date===selectedDate;html+=`<button type="button" class="${activeDay?'active':''}" onclick="dmDispatchSetDay('${date}')"><span>${safe(dayName(date,{weekday:'short'}))}</span><b>${Number(date.slice(8,10))}</b></button>`}return `<div class="dmv2DayStrip">${html}</div>`}
function masterCard(m,orders,conflicts){const mine=sortOrders(orders.filter(o=>assignedTo(o,m)));const hasConflict=mine.some(o=>conflicts.has(String(o.id)));const schedule=scheduleText(m);return `<section class="card dmv2MasterCard ${hasConflict?'conflict':''}"><div class="dmv2MasterHead"><div><h3>${safe(m.full_name||m.name||'Мастер')}</h3><p>${safe(schedule)}</p></div><div class="dmv2MasterBadges"><span>${mine.length} заяв.</span>${hasConflict?'<span class="danger">Конфликт</span>':''}</div></div>${mine.length?`<div class="dmv2MasterOrders">${mine.map(o=>`<button type="button" class="${conflicts.has(String(o.id))?'conflict':''}" onclick="openOrder('${safe(o.id)}')"><b>${safe(timeText(o))}</b><span>${safe(o.work||'Заявка')}</span></button>`).join('')}</div>`:'<p class="muted dmv2Empty">Нет заявок на этот день</p>'}</section>`}
function pageHtml(){
 const orders=dayOrders(),conflicts=conflictIds(orders),unassigned=sortOrders(orders.filter(isUnassigned)),masters=allMasters().sort((a,b)=>{const ac=orders.filter(o=>assignedTo(o,a)).some(o=>conflicts.has(String(o.id)))?1:0,bc=orders.filter(o=>assignedTo(o,b)).some(o=>conflicts.has(String(o.id)))?1:0;if(ac!==bc)return bc-ac;const al=orders.filter(o=>assignedTo(o,a)).length,bl=orders.filter(o=>assignedTo(o,b)).length;if(al!==bl)return bl-al;return String(a.full_name||a.name||'').localeCompare(String(b.full_name||b.name||''),'ru')});
 return `<div class="dmv2Dispatch"><section class="dmv2Header"><div><span>ДИСПЕТЧЕРСКАЯ</span><h2>${safe(dayName(selectedDate,{weekday:'long',day:'numeric',month:'long'}))}</h2></div><button class="primary" type="button" onclick="openOrderForm()">+ Заявка</button></section><div class="dmv2DayNav"><button class="secondary" type="button" onclick="dmDispatchShiftDay(-1)">←</button><button class="secondary dmv2Today" type="button" onclick="dmDispatchToday()">Сегодня</button><button class="secondary" type="button" onclick="dmDispatchShiftDay(1)">→</button></div>${dayStrip()}<div class="dmv2Metrics"><div><span>Заявок</span><b>${orders.length}</b></div><div><span>Без мастера</span><b>${unassigned.length}</b></div><div class="${conflicts.size?'danger':''}"><span>Конфликтов</span><b>${conflicts.size}</b></div><div><span>Мастеров</span><b>${masters.length}</b></div></div>${unassigned.length?`<section class="dmv2Section"><div class="dmv2SectionTitle"><div><span>ТРЕБУЕТ ДЕЙСТВИЯ</span><h3>Нужно назначить</h3></div><b>${unassigned.length}</b></div><div class="dmv2Unassigned">${unassigned.map(o=>orderCard(o,conflicts,{assign:true})).join('')}</div></section>`:''}<section class="dmv2Section"><div class="dmv2SectionTitle"><div><span>ЗАГРУЗКА</span><h3>Мастера</h3></div><b>${orders.length-unassigned.length} назнач.</b></div><div class="dmv2Masters">${masters.map(m=>masterCard(m,orders,conflicts)).join('')||'<p class="muted">Мастеров пока нет.</p>'}</div></section>${orders.length?`<section class="dmv2Section"><div class="dmv2SectionTitle"><div><span>ДЕНЬ</span><h3>Все заявки</h3></div><b>${orders.length}</b></div><div class="dmv2AllOrders">${sortOrders(orders).map(o=>orderCard(o,conflicts,{assign:isUnassigned(o)})).join('')}</div></section>`:'<section class="card dmv2NoOrders"><h3>На этот день заявок нет</h3><p class="muted">Можно перейти на соседний день или создать новую заявку.</p><button class="primary" onclick="openOrderForm()">+ Создать заявку</button></section>'}</div>`
}
// The shared calendar loads later; let it compose both views instead of replacing the day view.
window.BOS_DISPATCHER_DAY_HTML=()=>dispatcherMode()&&mobileMode()?pageHtml():'';
function render(){if(!dispatcherMode()||!mobileMode()||String(state?.page||'')!=='dispatch')return;if(window.BOS_UNIFIED_SCHEDULE_V102)return show('dispatch');const host=document.getElementById('content');if(!host)return;host.innerHTML=pageHtml();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page==='dispatch'))}
window.dmDispatchSetDay=function(date){selectedDate=dateOnly(date)||localToday();render()};
window.dmDispatchShiftDay=function(delta){selectedDate=addDays(selectedDate,Number(delta)||0);render()};
window.dmDispatchToday=function(){selectedDate=localToday();render()};
window.dmv2Assign=function(id){if(typeof window.dmAssignMaster==='function')return window.dmAssignMaster(String(id));if(typeof openOrder==='function')return openOrder(String(id))};
window.dmv2Move=function(id){if(typeof window.dmEditDateTime==='function')return window.dmEditDateTime(String(id));if(typeof window.openDispatcherReschedule==='function')return window.openDispatcherReschedule(String(id));if(typeof openOrder==='function')return openOrder(String(id))};
const baseDispatch=pages.dispatch;
pages.dispatch=function(){if(!window.BOS_UNIFIED_SCHEDULE_V102&&dispatcherMode()&&mobileMode()){setTimeout(render,0);return pageHtml()}return baseDispatch()};
window.addEventListener('resize',()=>{const now=mobileMode();if(now===wasMobile)return;wasMobile=now;if(dispatcherMode()&&String(state?.page||'')==='dispatch'&&typeof show==='function')show('dispatch')});
const style=document.createElement('style');style.textContent=`
@media(max-width:${MOBILE_MAX}px){
 .dmv2Dispatch{display:flex;flex-direction:column;gap:11px;padding-bottom:10px}.dmv2Header{display:flex;align-items:flex-end;justify-content:space-between;gap:12px}.dmv2Header>div{min-width:0}.dmv2Header span,.dmv2SectionTitle span{display:block;font-size:10px;font-weight:800;letter-spacing:.11em;color:#8297aa}.dmv2Header h2{margin:3px 0 0;font-size:21px;line-height:1.15;text-transform:capitalize}.dmv2Header>.primary{flex:0 0 auto;min-height:44px;padding:8px 12px}.dmv2DayNav{display:grid;grid-template-columns:44px 1fr 44px;gap:7px}.dmv2DayNav .secondary{min-height:44px;padding:6px}.dmv2Today{font-weight:700}.dmv2DayStrip{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:5px}.dmv2DayStrip button{min-width:0;border:1px solid rgba(255,255,255,.08);border-radius:11px;background:rgba(15,29,44,.88);color:inherit;padding:7px 2px;text-align:center}.dmv2DayStrip button span{display:block;font-size:9px;color:#8ea3b6;text-transform:capitalize;overflow:hidden}.dmv2DayStrip button b{display:block;margin-top:2px;font-size:14px}.dmv2DayStrip button.active{border-color:rgba(76,169,255,.7);background:rgba(43,120,190,.24)}.dmv2DayStrip button.active span,.dmv2DayStrip button.active b{color:#bfe3ff}.dmv2Metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px}.dmv2Metrics>div{padding:9px 5px;border:1px solid rgba(255,255,255,.08);border-radius:12px;background:rgba(15,29,44,.88);text-align:center}.dmv2Metrics span{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:9px;color:#8ea3b6}.dmv2Metrics b{display:block;margin-top:2px;font-size:18px}.dmv2Metrics .danger{border-color:rgba(229,92,92,.4)}.dmv2Metrics .danger b{color:#ff9292}.dmv2Section{display:flex;flex-direction:column;gap:8px}.dmv2SectionTitle{display:flex;align-items:flex-end;justify-content:space-between;gap:10px;padding:3px 1px}.dmv2SectionTitle h3{margin:2px 0 0;font-size:16px}.dmv2SectionTitle>b{font-size:11px;color:#91a5b8}.dmv2Unassigned,.dmv2AllOrders,.dmv2Masters{display:flex;flex-direction:column;gap:8px}.dmv2Order{margin:0;padding:12px 13px;border-radius:15px}.dmv2Order.conflict{border-color:rgba(229,92,92,.55)}.dmv2OrderTop{display:flex;align-items:center;justify-content:space-between;gap:8px}.dmv2OrderTop>div{display:flex;align-items:baseline;gap:7px}.dmv2OrderTop>div b{font-size:15px}.dmv2OrderTop>div span{font-size:10px;color:#8197aa}.dmv2Order h3{margin:7px 0 2px;font-size:14px}.dmv2Client,.dmv2Address,.dmv2MasterName{margin:3px 0;font-size:12px}.dmv2MasterName{font-weight:700;color:#abd9ff}.dmv2Status,.dmv2Alert{font-size:10px;padding:4px 7px;border-radius:999px;background:rgba(68,132,190,.2);color:#acd8ff}.dmv2Alert{background:rgba(229,92,92,.14);color:#ff9999}.dmv2Actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;margin-top:9px;padding-top:8px;border-top:1px solid rgba(255,255,255,.07)}.dmv2Actions .secondary{display:flex;align-items:center;justify-content:center;min-height:44px;margin:0;border-radius:10px;font-size:11px;text-decoration:none}.dmv2MasterCard{margin:0;padding:12px 13px;border-radius:15px}.dmv2MasterCard.conflict{border-color:rgba(229,92,92,.45)}.dmv2MasterHead{display:flex;align-items:flex-start;justify-content:space-between;gap:8px}.dmv2MasterHead h3{margin:0;font-size:14px}.dmv2MasterHead p{margin:3px 0 0;color:#8ea3b6;font-size:11px}.dmv2MasterBadges{display:flex;gap:5px;flex-wrap:wrap;justify-content:flex-end}.dmv2MasterBadges span{font-size:10px;padding:4px 7px;border-radius:999px;background:rgba(68,132,190,.18);color:#acd8ff}.dmv2MasterBadges .danger{background:rgba(229,92,92,.14);color:#ff9999}.dmv2MasterOrders{display:flex;gap:6px;overflow-x:auto;margin-top:9px;padding-bottom:1px;scrollbar-width:none}.dmv2MasterOrders::-webkit-scrollbar{display:none}.dmv2MasterOrders button{flex:0 0 auto;display:flex;gap:6px;align-items:center;border:1px solid rgba(255,255,255,.08);border-radius:9px;background:rgba(8,18,29,.72);color:inherit;padding:7px 9px}.dmv2MasterOrders button b{font-size:11px}.dmv2MasterOrders button span{font-size:10px;color:#91a6b8;max-width:120px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.dmv2MasterOrders button.conflict{border-color:rgba(229,92,92,.48)}.dmv2Empty{margin:8px 0 0;font-size:11px}.dmv2NoOrders{text-align:center;padding:20px 14px}.dmv2NoOrders h3{margin:0 0 5px}.dmv2NoOrders p{margin:0 0 12px}
}
@media(max-width:390px){.dmv2Metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.dmv2Metrics span{font-size:10px}}
`;
document.head.appendChild(style);
})();


